cat > s4.mjs <<'EOF'
import { chromium } from 'playwright';
const b = await chromium.launch({headless:true});
const p = await b.newPage();
await p.goto('http://127.0.0.1:54569');
await p.fill('#email','ops@lab.test');
await p.fill('#password','lab-ops-pass');
await p.click('button[type=submit]');
await p.waitForLoadState('networkidle');
await p.goto('http://127.0.0.1:54569/settings');
await p.waitForLoadState('networkidle');
const f = p.frameLocator('iframe[title="Notification settings"]');
await f.locator('#th').fill('755');
await f.locator('#sw').click();
await f.locator('#sv').click();
await f.locator('#ok').waitFor();
console.log('threshold', await f.locator('#th').inputValue(), 'switch', await f.locator('#sw').textContent(), 'status', await f.locator('#ok').textContent());
await b.close();
EOF
